We can apply this diff

```
diff --git a/cpld/lattice/lattice.cpp b/cpld/lattice/lattice.cpp
index 2931703..7dfa141 100644
--- a/cpld/lattice/lattice.cpp
+++ b/cpld/lattice/lattice.cpp
@@ -2,6 +2,7 @@

 #include <phosphor-logging/lg2.hpp>

+#include <algorithm>
 #include <fstream>
 #include <map>
 #include <thread>
@@ -44,7 +45,7 @@ sdbusplus::async::task<bool> CpldLatticeManager::sendrecv(
     std::vector<uint8_t>& writeData, size_t readSize,
     std::vector<uint8_t>& readData) const noexcept
 {
-    readData.resize(readSize, 0);
+    readData.resize(std::ranges::min(readSize, (size_t)1), 0);

     bool success = co_await i2cInterface.sendReceive(
         writeData.data(), writeData.size(), readData.data(), readSize);
@@ -607,7 +608,6 @@ sdbusplus::async::task<bool> CpldLatticeManager::disableConfigInterface()
 {
     std::vector<uint8_t> command = {commandDisableConfigInterface, 0x0, 0x0};
     std::vector<uint8_t> read;
-    // NOLINTNEXTLINE(clang-analyzer-core.uninitialized.Branch)
     co_return co_await sendrecv(command, 0, read);
 }

```

to resolve the issue about the uninitialized branch.
Which prevents the vector from being resized to 0.

Since later ```.data()``` is called on the vector it may be good to have a vector of nonzero size.
